# Generated by build.py from recipe.yml for recipe smbs-read-a-share-over-tls. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--auth', 'ntlmv1', '-u', 'alice:s3cret', 'smbs://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --cacert server.pem -u alice:s3cret smbs://127.0.0.1:8080/docs/readme.txt } finally { Stop-Process $server0 }
